export default async function checkCandidateCurrent(id: string, event: string, coordinate: string):Promise<SystemCandidateGate>{
 return systemCandidateRead.confirm(id, event, coordinate);
}

import {systemCandidateRead} from "natlang:services";
import type {SystemCandidateFrontier} from "../../types.js";
/** Read the actual native VCS comparison at one staged event. */
export default async function readDeltaFrontier(id: string, event: string):Promise<SystemCandidateFrontier>{
 return systemCandidateRead.compare(id, event);
}

import {systemCandidateRead} from "natlang:services";
import type {SystemCandidatePreview} from "../../types.js";
/** Read bounded base, local and incoming evidence at an exact file coordinate. */
export default async function readFileTriplet(id: string, event: string, coordinate: string):Promise<SystemCandidatePreview>{
 return systemCandidateRead.preview(id, event, coordinate);
}

import {systemCandidateHandoff} from "natlang:services";
import type {SystemCandidatePlan, SystemCandidateReceipt} from "../types.js";
/** Record an approved private diagnosis for one current file coordinate. */
export default async function recordCandidateHandoff(id: string, event: string, coordinate: string, plan: SystemCandidatePlan):Promise<SystemCandidateReceipt | null>{
 return systemCandidateHandoff.record(id, event, coordinate, plan);
}

import {systemCandidateRead} from "natlang:services";
import type {SystemCandidateReadback} from "../types.js";
/** Independently read the exact private file and current owned review. */
export default async function verifyCandidateHandoff(id: string, path: string | null):Promise<SystemCandidateReadback>{
 return systemCandidateRead.readback(id, path);
}

import {recoveryHandoffLink} from "natlang:services";
import type {RecoveryHandoffDirective} from "./types.js";
/** Read the exact current owner directive and local recipient. */
export default async function readDirective():Promise<RecoveryHandoffDirective>{
 return recoveryHandoffLink.discover();
}

import {terminalRepairObserve} from "natlang:services";
import type {TerminalRepairCheck} from "../../types.js";
/** Read the installed production source and baseline native checks at this exact app's current revision. */
export default async function observeTerminalApp(appId: string):Promise<TerminalRepairCheck>{
 return terminalRepairObserve.read(appId);
}

import {terminalRepairFinal} from "natlang:services";
import type {TerminalRepairCheck} from "../../types.js";
/** Independently recheck the production build and original focused native suite. */
export default async function checkFinalSource(appId: string, revision: string):Promise<TerminalRepairCheck>{
 return terminalRepairFinal.verify(appId, revision);
}

import {terminalRepairArtifact} from "natlang:services";
import type {TerminalRepairArtifact} from "../../types.js";
/** Read the build store's terminal runtime artifact for the verified revision. */
export default async function readTerminalArtifact(appId: string, revision: string):Promise<TerminalRepairArtifact | null>{
 return terminalRepairArtifact.read(appId, revision);
}

import {workspaceClaimRead} from "natlang:services";
import type {ClaimIndex} from "./types.js";
/** Discover the active workspace claim packet and any similarly named archive. */
export default async function listClaimScopes():Promise<ClaimIndex>{
 return workspaceClaimRead.list();
}

import {workspaceClaimRead} from "natlang:services";
import type {ClaimEvidence} from "./types.js";
/** Observe independent native file and TestKit receipts for the selected candidate and earlier state. */
export default async function readClaimEvidence(id: string):Promise<ClaimEvidence | null>{
 return workspaceClaimRead.observe(id);
}

import {workspaceClaimRead} from "natlang:services";
import type {ClaimPacket} from "./types.js";
/** Read the exact selected packet tied to an owned candidate and named acceptance statements. */
export default async function readClaimPacket(id: string):Promise<ClaimPacket | null>{
 return workspaceClaimRead.read(id);
}

import {workspaceClaimHandoff} from "natlang:services";
import type {ClaimHandoff, WorkspaceClaimReview} from "./types.js";
/** Retain the caller-authorized private claim decision with exact evidence. */
export default async function writeClaimNote(report: WorkspaceClaimReview):Promise<ClaimHandoff | null>{
 return workspaceClaimHandoff.stage(report);
}

import {terminalCheckRun} from "natlang:services";
import type {TerminalCheckResult} from "../types.js";
/** Execute one check from the caller's observed terminal plan. */
export default async function performCheck(assignmentReceipt: string, checkId: string):Promise<TerminalCheckResult>{
 return terminalCheckRun.execute(assignmentReceipt, checkId);
}

import {terminalCheckRead} from "natlang:services";
import type {TerminalPlan} from "../types.js";
/** Read the caller's exact set of bounded process checks and their dependencies. */
export default async function readAssignedChecks(operationId: string):Promise<TerminalPlan>{
 return terminalCheckRead.observe(operationId);
}

import {checklistKeys} from "natlang:services";
import type {ChecklistScreen, ItemKey} from "../../types.js";
/** Send one authorized item key to the running checklist and read its updated screen. */
export default async function sendToggle(key: ItemKey):Promise<ChecklistScreen>{
 return checklistKeys.toggle(key);
}

import {checklistOpen} from "natlang:services";
import type {ChecklistScreen} from "../../types.js";
/** Obtain the screen of the caller's newly launched checklist. */
export default async function launchApp():Promise<ChecklistScreen>{
 return checklistOpen.launch();
}

import {checklistResume} from "natlang:services";
import type {ChecklistScreen} from "../../types.js";
/** Observe the retained checklist state after continuing the assigned terminal session. */
export default async function continueApp(kind: "reattach" | "restart"):Promise<ChecklistScreen>{
 return checklistResume.resume(kind);
}
